def _hkdf(_ikm,_length,_salt,_info):
    if not _salt:_salt=b'\x00'*32
    _prk=_hm.new(_salt,_ikm,_hl.sha256).digest()
    _t=b'';_okm=b'';_i=1
    while len(_okm)<_length:
        _t=_hm.new(_prk,_t+_info+bytes([_i]),_hl.sha256).digest();_okm+=_t;_i+=1
    return _okm[:_length]

